"use client";

/**
 * Supporter grid: a field of empty avatar rings switches on in a wave that
 * starts at the centre, while the supporter count under it climbs. A thank-you
 * line closes the shot. The gratitude beat of a launch film.
 *
 * Written by Better Design. Painted from the theme prop.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, interpolate, random, useCurrentFrame } from "remotion";
import { easings, pickFont, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600", "700"], subsets: ["latin"] });

const COLS = 13;
const ROWS = 5;
const SIZE = 88;
const GAP = 26;
const WAVE_AT = 8;
/** Frames the wave takes to reach the far corner. */
const WAVE_FRAMES = 52;
const POP_FRAMES = 12;
const LINE_AT = 72;

export interface SupporterGridProps {
  /** Names drawn as initials. The grid repeats them when it has more cells. */
  names?: string[];
  /** The number the counter lands on. Use a real figure. */
  count?: number;
  /** What the counter counts. */
  countLabel?: string;
  /** The closing thank-you line. */
  line?: string;
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const DEFAULT_NAMES = [
  "Maya Lin", "Jonas Keller", "Priya Shah", "Leo Marin", "Ines Rocha", "Sam Taylor", "Noor Aziz",
  "Theo Brandt", "Hana Watanabe", "Omar Diallo", "Lena Fischer", "Ravi Patel", "Ada Moreau", "Kofi Mensah",
  "Elif Demir", "Tom Novak", "Sara Costa", "Yuki Mori", "Ben Ortiz", "Mila Ivanova",
];

const initials = (name: string): string =>
  name.split(/\s+/).filter(Boolean).slice(0, 2).map((w) => w[0]?.toUpperCase() ?? "").join("");

const clamp = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

/** A grid of supporters lighting up from the centre, a climbing count and a thank-you. */
export function SupporterGrid({
  names = DEFAULT_NAMES,
  count = 1240,
  countLabel = "people backed the launch",
  line = "Thank you for building this with us.",
  theme: themeOverride,
  font,
}: SupporterGridProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const family = pickFont(font, theme, INTER);
  const pool = names.length > 0 ? names : DEFAULT_NAMES;

  const cx = (COLS - 1) / 2;
  const cy = (ROWS - 1) / 2;
  const maxDist = Math.hypot(cx, cy);

  const lineT = easings.out(interpolate(frame, [LINE_AT, LINE_AT + 18], [0, 1], clamp));
  const enter = easings.out(interpolate(frame, [0, 12], [0, 1], clamp));
  const finalText = count.toLocaleString("en-US");

  const cells = Array.from({ length: COLS * ROWS }, (_, i) => {
    const col = i % COLS;
    const row = Math.floor(i / COLS);
    const dist = Math.hypot(col - cx, row - cy) / maxDist;
    const at = WAVE_AT + dist * WAVE_FRAMES + random(`jit-${i}`) * 6;
    return interpolate(frame, [at, at + POP_FRAMES], [0, 1], clamp);
  });
  // The count follows the avatars that have switched on, so number and wave stay in step.
  const countT = cells.reduce((sum, t) => sum + t, 0) / cells.length;

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family, alignItems: "center", justifyContent: "center", gap: 64 }}>
      <div style={{ display: "grid", gridTemplateColumns: `repeat(${COLS}, ${SIZE}px)`, gap: GAP, opacity: enter }}>
        {cells.map((t, i) => {
          const pop = easings.out(t);
          // A small overshoot as each avatar switches on.
          const scale = 0.72 + pop * 0.28 + Math.sin(t * Math.PI) * 0.1;
          const tone = Math.floor(random(`tone-${i}`) * 3);
          const fill = tone === 0 ? theme.primary : tone === 1 ? withAlpha(theme.primary, 0.16) : withAlpha(theme.foreground, 0.08);
          const ink = tone === 0 ? theme.primaryForeground : tone === 1 ? theme.primary : theme.foreground;
          const name = pool[(i * 7) % pool.length] ?? "";
          return (
            <div key={i} style={{ position: "relative", width: SIZE, height: SIZE }}>
              <div style={{ position: "absolute", inset: 0, borderRadius: SIZE / 2, border: `2px dashed ${withAlpha(theme.mutedForeground, 0.28 * (1 - pop))}` }} />
              <div
                style={{
                  position: "absolute", inset: 0, borderRadius: SIZE / 2, background: fill, color: ink,
                  display: "flex", alignItems: "center", justifyContent: "center", fontSize: 30, fontWeight: 600,
                  opacity: pop, transform: `scale(${scale})`,
                }}
              >
                {initials(name)}
              </div>
            </div>
          );
        })}
      </div>

      <div style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 14 }}>
        <div style={{ display: "flex", alignItems: "baseline", gap: 24 }}>
          <div style={{ position: "relative", fontSize: 104, fontWeight: 700, letterSpacing: "-0.04em", lineHeight: 1, color: theme.foreground, fontVariantNumeric: "tabular-nums" }}>
            <span style={{ visibility: "hidden" }}>{finalText}</span>
            <span style={{ position: "absolute", right: 0, top: 0 }}>{Math.round(count * countT).toLocaleString("en-US")}</span>
          </div>
          <div style={{ fontSize: 40, fontWeight: 500, color: theme.mutedForeground }}>{countLabel}</div>
        </div>
        <div style={{ fontSize: 44, fontWeight: 600, letterSpacing: "-0.01em", color: theme.primary, opacity: lineT, transform: `translateY(${(1 - lineT) * 14}px)` }}>
          {line}
        </div>
      </div>
    </AbsoluteFill>
  );
}
